SELECT ics10_checklist_id AS checklist_id, ics10_company_id AS company_id, ics10_content AS content, ics10_criterion AS criterion, ics10_use_yn AS use_yn, ics10_checklist_m_class_id AS checklist_m_class_id, ics10_seq AS seq, ics21_checklist_l_class_nm AS check_l_class_name, ics23_checklist_m_class_nm AS check_m_class_name, ics21_checklist_l_class_id AS check_l_class_id, ics21_seq AS check_l_class_seq, ics23_seq AS check_m_class_seq FROM ics10_checklist INNER JOIN ics_class ON ics23_checklist_m_class_id = ics10_checklist_m_class_id WHERE 1=1 AND ics10_company_id = #{companyId} AND ics10_use_yn LIKE #{useYn}
AND ics21_checklist_l_class_id = #{checklistLClassId}
AND ics23_checklist_m_class_id = #{checklistMClassId}
AND CONCAT( ics21_checklist_l_class_nm , ics23_checklist_m_class_nm , ics10_content , ics10_criterion ) LIKE #{searchText} ORDER BY ics21_seq, ics23_seq, ics10_seq, ics10_content

mapper.update:
UPDATE ics10_checklist
   SET ics10_content               = #{req.content},
       ics10_criterion             = #{req.criterion},
       ics10_use_yn                = #{req.useYn},
       ics10_checklist_m_class_id  = #{req.checklistMClassId},
       ics10_seq                   = #{req.seq}
 WHERE ics10_checklist_id = #{req.checklistId}
   AND ics10_company_id   = #{companyId}

UPDATE ics11_checklist_company
   SET ics11_use_yn = #{useYn}
 WHERE ics11_company_id   = #{companyId}
   AND ics11_checklist_id = #{checklistId}

