SELECT CAST(ics23_checklist_m_class_id AS VARCHAR) AS code, ics23_checklist_m_class_nm AS name FROM ics_class WHERE 1=1
AND ics23_checklist_l_class_id = #{checklistLClassId}
GROUP BY ics23_company_id, ics23_checklist_m_class_id, ics23_checklist_m_class_nm, ics23_seq ORDER BY ics23_seq

SELECT ics10_checklist_id AS checklist_id, ics10_company_id AS company_id, ics10_content AS content, ics10_criterion AS criterion, ics10_seq AS seq, COALESCE(ics11_use_yn, 'true') AS use_yn, ics21_checklist_l_class_nm AS check_l_class_name, ics21_checklist_l_class_id AS check_l_class_id, ics23_checklist_m_class_nm AS check_m_class_name, ics23_checklist_m_class_id AS checklist_m_class_id, ( SELECT sch22_write_group_nm FROM sch22_write_group WHERE sch22_write_group_id = ics11_write_group_id AND sch22_company_id = #{companyId} ) AS write_group_name FROM ics10_checklist INNER JOIN ics_class ON ics23_checklist_m_class_id = ics10_checklist_m_class_id LEFT OUTER JOIN ics11_checklist_company ON ics11_checklist_id = ics10_checklist_id AND ics11_company_id = #{companyId} WHERE 1=1 AND ics10_company_id IN (0, #{companyId}) AND ics10_use_yn = 'true' AND COALESCE(ics11_use_yn, 'true') LIKE #{useYn}
AND ics21_checklist_l_class_id = #{checklistLClassId}
AND ics23_checklist_m_class_id = #{checklistMClassId}
AND CONCAT( ics21_checklist_l_class_nm , ics23_checklist_m_class_nm , ics10_content , ics10_criterion ) LIKE #{searchText} ORDER BY ics21_seq, ics23_seq, ics10_seq, ics10_content

SELECT COUNT(*)
  FROM ics15_checklist_write
 WHERE ics15_company_id   = #{companyId}
   AND ics15_checklist_id = #{checklistId}

SELECT ics11_checklist_company_id
  FROM ics11_checklist_company
 WHERE ics11_checklist_id = #{checklistId}
   AND ics11_company_id   = #{companyId}
 LIMIT 1

